import { ClassicEditor } from "@ckeditor/ckeditor5-editor-classic";
import { Essentials } from "@ckeditor/ckeditor5-essentials";
import { AutoLink, Link } from '@ckeditor/ckeditor5-link';
import { Paragraph, ParagraphButtonUI } from "@ckeditor/ckeditor5-paragraph";
import { Heading, HeadingButtonsUI } from "@ckeditor/ckeditor5-heading";
import { Bold, Italic, Underline } from "@ckeditor/ckeditor5-basic-styles";
import { GeneralHtmlSupport } from "@ckeditor/ckeditor5-html-support";
import { Style } from "@ckeditor/ckeditor5-style";
import { SourceEditing } from "@ckeditor/ckeditor5-source-editing";


function downloadPageAsHTML(fileName) {
  // Get the entire HTML content of the current document
  const htmlString = `<!DOCTYPE html>\n${document.documentElement.outerHTML}`;

  // Create a Blob from the HTML string
  const blob = new Blob([htmlString], { type: "text/html" });

  // Create a link element
  const link = document.createElement("a", {id:'download'});

  // Set the href attribute to the Blob URL
  link.href = URL.createObjectURL(blob);

  // Set the download attribute to specify the filename
  link.download = fileName;

  // Simulate a click on the link to trigger the download
  link.click();

  // Clean up by revoking the Blob URL
  URL.revokeObjectURL(link.href);
}


let editor;

document.querySelector("#editing").addEventListener("change", function () {
  if (this.checked) {
    console.log("Initializing editor...");
    console.assert(
      (editor === null) | (editor === undefined),
      "Editor was already initialized"
    );

    //change editable element
    ClassicEditor.create(document.querySelector("#editor"), {
      plugins: [
        GeneralHtmlSupport,
        Essentials,
        AutoLink,
        Link,
        Paragraph,
        Heading,
        Bold,
        Italic,
        Underline,
        Style,
        SourceEditing,
      ],
      toolbar: [
        "undo",
        "redo",
        "|",
        "bold",
        "italic",
        "underline",
        "link",
        "|",
        "heading",
        "style",
        "|",
        "sourceEditing",
      ],
      style: {
        definitions: [
          {
            name: "HTML Definition",
            element: "span",
            classes: ["HTML_Definition"],
          },
          {
            name: "HTML Code",
            element: "span",
            classes: ["HTML_Code"],
          },
          {
            name: "HTML Keyboard",
            element: "span",
            classes: ["HTML_Keyboard"],
          },
        ],
      },
      heading: {
        options: [
          {
            model: "paragraph",
            title: "Paragraph",
            class: "ck-heading_paragraph",
          },
          {
            model: "heading1",
            view: "h1",
            title: "Heading 1",
            class: "ck-heading_heading1",
          },
          {
            model: "heading2",
            view: "h2",
            title: "Heading 2",
            class: "ck-heading_heading2",
          },
          {
            model: "heading3",
            view: "h3",
            title: "Heading 3",
            class: "ck-heading_heading3",
          },
          {
            model: "heading4",
            view: "h4",
            title: "Heading 4",
            class: "ck-heading_heading4",
          },
          {
            model: "heading5",
            view: "h5",
            title: "Heading 5",
            class: "ck-heading_heading5",
          },
          {
            model: "heading6",
            view: "h6",
            title: "Heading 6",
            class: "ck-heading_heading6",
          },
        ],
      },
      htmlSupport: {
        allow: [
          {
            name: /.*/,
            attributes: true,
            classes: true,
            styles: true,
          },
        ],
      },
      updateSourceElementOnDestroy: true,
    })
      .then((newEditor) => {
        editor = newEditor;
        console.log(editor);
      })
      .catch((error) => {
        console.error(error);
      });
  } else {
    if (editor) {
      console.log("Closing editor...");
      editor.destroy();
      editor = null;
    }
  }
});

// Assuming there is a <button id="submit">Submit</button> in your application.

document.querySelector("#download_btn").addEventListener("click", () => {
  //close editor if it exists
  if (editor) {
    editor.destroy();
    editor = null;
  }
  var filename = location.pathname.substring(
    location.pathname.lastIndexOf("/") + 1,
    location.pathname.lastIndexOf(".")
  );
  downloadPageAsHTML(`${filename}_updated.html`);
});